    registerTool({
      name: 'novel_store',
      description: '查看或设置项目存储根目录。默认自动解析：会话工作区（cwd）→ fs 默认基路径探测 → .root 指针文件 → 沙箱回退根。当自动解析不对时，用 action=set root=绝对路径 显式指定（会写入 <回退根>/novel-assistant/.root 指针，供以后会话复用）。report 同时输出当前激活项目与多项目清单。',
      parameters: {
        action: { type: 'string', enum: ['report', 'set'], description: 'report=输出诊断；set=设置存储根目录（需 root 参数）' },
        root: { type: 'string', description: '绝对路径，仅 action=set 时必填' },
        default: { type: 'string', description: '设置默认项目（action=set 时）：传项目 id 设为默认，传空字符串清除；重启后自动激活默认项目' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        if (args.action === 'set') {
          if (args.default !== undefined) {
            projectsMeta.default = String(args.default).trim()
            await writeProjectsMeta()
            await persist()
            return projectsMeta.default ? '默认项目已设为：' + projectsMeta.default + '（重启后自动激活；novel_state view=projects 查看）' : '默认项目已清除'
          }
          if (!args.root || !/^[a-zA-Z]:[\\/]|^\\/.test(args.root)) return 'root 必须是绝对路径：' + args.root
          rootCache = trimSlash(args.root)
          try {
            const home = (typeof process !== 'undefined' && (process.env.HOME || process.env.USERPROFILE)) || ''
            const targets = [await fs.resolve('novel-assistant/.root', { cwd: sp.workspaceRoot || '.' })]
            if (home) targets.push(await fs.resolve(home + '/.dsh/novel-assistant/.root'))
            const wrote = []
            for (const t of targets) { try { await fs.writeText(t, rootCache); wrote.push(fs.processPath(t)) } catch (e2) {} }
            await persist()
            return '存储根目录已设为：' + rootCache + '（指针已写入 ' + wrote.join('、') + '）'
          } catch (e) {
            await persist()
            return '存储根目录已设为（本次会话）：' + rootCache + '；但指针写入失败：' + ((e && e.message) || e)
          }
        }
        const session = findSession()
        let policyInfo = null
        try {
          const p = policyForSession(session)
          if (p) policyInfo = { mode: p.mode, workspaceRoot: p.workspaceRoot }
        } catch (e) {}
        let defaultBase = null
        try { defaultBase = fs.processPath(await fs.resolve('.')) } catch (e) {}
        return JSON.stringify({
          workspaceRoot: sp.workspaceRoot || '.',
          fsDefaultBase: defaultBase,
          sessionCwd: sessionCwd(),
          sessionFoundCwd: session && session.meta ? session.meta.cwd : null,
          sessionPolicy: policyInfo,
          currentRoot: await resolveRoot(),
          activeProject: projectsMeta.active,
          defaultProject: projectsMeta.default || '',
          projects: projectsMeta.projects.map((p) => p.id + '《' + p.title + '》' + (p.id === projectsMeta.active ? '【当前】' : '')).join('；') || '（无）',
        }, null, 2)
      },
    })
